mapper.select:
SELECT m.menu_id, m.parent_menu_id, m.menu_code, m.menu_name, m.menu_type, m.route_path, m.component, m.icon, m.visible, m.status, m.sort_no, m.remark FROM exp_menu m
AND m.menu_code LIKE CONCAT('%', #{menuCode}, '%')
AND m.menu_name LIKE CONCAT('%', #{menuName}, '%')
AND m.menu_type = #{menuType}
AND m.status = #{status}
ORDER BY m.sort_no ASC

SELECT COUNT(1)
FROM exp_menu
WHERE menu_code = #{menuCode}

    AND menu_id != #{excludeMenuId}

SELECT m.menu_id, m.parent_menu_id, m.menu_code, m.menu_name, m.menu_type, m.route_path, m.component, m.icon, m.visible, m.status, m.sort_no, m.remark FROM exp_menu m WHERE m.menu_id IN
#{menuId}
ORDER BY m.sort_no ASC
